using Npgsql;

namespace Aethera.Api.Tests;

/// <summary>Runs against a real PostgreSQL (see <see cref="RequiresDatabaseFactAttribute"/>).</summary>
public sealed class PersistenceIntegrationTests(TestDatabaseFixture database) : IClassFixture<TestDatabaseFixture>
{
    private static readonly DateTimeOffset Now = new(2026, 10, 3, 12, 0, 0, TimeSpan.Zero);

    private sealed record Seed(Guid OrgId, Guid ProjectId, Guid EnvId, Guid ServerId, Guid UserId);

    private static string Unique(string prefix) => prefix + "-" + Guid.NewGuid().ToString("N")[..12];

    private async Task<Seed> SeedBaseAsync()
    {
        using var lease = database.NewContext();
        var db = lease.Db;
        var org = new Organization { Name = "Turn One", Slug = Unique("org") };
        var user = new User($"{Unique("u")}@example.com", "Owner");
        var project = new Project { Organization = org, Name = "Turn One", Slug = "turn-one" };
        var env = new ProjectEnvironment { Project = project, Name = "Production", Slug = "production", IsProduction = true };
        var server = new Server { Organization = org, Name = Unique("srv"), Host = "203.0.113.10" };
        db.AddRange(org, user, project, env, server);
        await db.SaveChangesAsync();
        return new Seed(org.Id, project.Id, env.Id, server.Id, user.Id);
    }

    private static Secret NewSecret(Guid orgId, string name)
    {
        var secret = new Secret { OrganizationId = orgId, Name = name };
        secret.AddVersion([1, 2, 3], new byte[12], [9], new byte[12], masterKeyVersion: 1, Now);
        return secret;
    }

    private static Application NewApp(Seed seed, string? slug = null) => new()
    {
        EnvironmentId = seed.EnvId,
        ServerId = seed.ServerId,
        Name = "API",
        Slug = slug ?? Unique("api"),
    };

    private async Task<Guid> SeedAppAsync(Seed seed)
    {
        using var lease = database.NewContext();
        var app = NewApp(seed);
        lease.Db.Add(app);
        await lease.Db.SaveChangesAsync();
        return app.Id;
    }

    private static async Task<DbUpdateException> AssertConstraintAsync(Func<Task> action, string sqlState)
    {
        var ex = await Assert.ThrowsAsync<DbUpdateException>(action);
        var pg = Assert.IsType<PostgresException>(ex.InnerException);
        Assert.Equal(sqlState, pg.SqlState);
        return ex;
    }

    private const string UniqueViolation = "23505";
    private const string CheckViolation = "23514";

    [RequiresDatabaseFact]
    public async Task Migration_CreatesExpectedTables()
    {
        using var lease = database.NewContext();
        var tables = await lease.Db.Database
            .SqlQueryRaw<string>("SELECT table_name AS \"Value\" FROM information_schema.tables WHERE table_schema = 'public'")
            .ToListAsync();

        foreach (var expected in new[]
        {
            "organizations", "users", "organization_members", "teams", "team_members", "api_tokens", "user_sessions",
            "projects", "environments", "servers", "join_tokens", "certificate_authorities", "agent_certificates",
            "workloads", "git_sources", "build_configs", "image_sources", "compose_sources", "git_credentials",
            "webhook_endpoints", "webhook_deliveries", "workload_ports", "environment_variables", "secrets", "secret_versions",
            "volumes", "networks", "workload_networks", "domains", "registries", "deployments", "deployment_steps", "builds",
            "jobs", "log_chunks", "audit_events", "resource_events", "idempotency_records", "settings", "metric_samples", "images",
        })
            Assert.Contains(expected, tables);
    }

    [RequiresDatabaseFact]
    public async Task ProjectEnvironmentApplicationDeployment_GraphRoundTrips()
    {
        var seed = await SeedBaseAsync();
        Guid appId, deploymentId;

        using (var lease = database.NewContext())
        {
            var db = lease.Db;
            var secret = NewSecret(seed.OrgId, "GITHUB_TOKEN");
            secret.EnvironmentId = seed.EnvId;
            var credential = new GitCredential
            {
                OrganizationId = seed.OrgId, Name = Unique("gh"), Kind = GitCredentialKind.Token, Provider = GitProvider.GitHub, Secret = secret,
            };
            var app = NewApp(seed);
            app.SourceKind = ApplicationSourceKind.Git;
            app.Runtime.RestartPolicy = RestartPolicy.OnFailure;
            app.Runtime.DeploymentStrategy = DeploymentStrategies.LowDowntime;
            app.Runtime.CpuLimit = 1.5;
            app.Runtime.MemoryLimitBytes = 512L * 1024 * 1024;
            app.Runtime.HealthCheck = new HealthCheckConfig { Type = HealthCheckType.Http, Path = "/health", Port = 8080, Retries = 5 };
            app.GitSource = new GitSource
            {
                Provider = GitProvider.GitHub, RepositoryUrl = "https://github.com/turn-one/api.git", Branch = "main",
                AutoDeploy = true, GitCredential = credential,
            };
            app.BuildConfig = new BuildConfig
            {
                Engine = BuildEngines.Dockerfile, DockerfilePath = "Dockerfile",
                BuildArgs = new Dictionary<string, string> { ["NODE_ENV"] = "production" },
            };
            app.Ports.Add(new WorkloadPort { ContainerPort = 8080, IsHttp = true });
            app.EnvironmentVariables.Add(new EnvironmentVariable { Key = "DATABASE_URL", Secret = secret, IsBuildTime = false });
            app.EnvironmentVariables.Add(new EnvironmentVariable { Key = "NODE_ENV", Value = "production", IsBuildTime = true });
            app.Volumes.Add(new Volume { Name = "api-data", MountPath = "/data", BackupEnabled = true });
            app.Domains.Add(NewDomain(seed, "API.Turn-One.Example"));
            db.Add(app);
            await db.SaveChangesAsync();
            appId = app.Id;

            var number = app.AllocateDeploymentNumber();
            var deployment = Deployment.Queue(app.Id, seed.EnvId, seed.ServerId, number, DeploymentTrigger.Webhook, Now,
                DeploymentStrategies.LowDowntime);
            deployment.CommitSha = "0123456789abcdef";
            deployment.Ref = "main";
            deployment.TriggeredByUserId = seed.UserId;
            deployment.Start("""{"runtime":{"restartPolicy":"OnFailure"}}""", Now.AddSeconds(1));
            deployment.BeginStep(DeploymentStep.Source, Now.AddSeconds(1));
            deployment.CompleteStep(DeploymentStep.Source, Now.AddSeconds(2));
            deployment.BeginStep(DeploymentStep.Build, Now.AddSeconds(2));
            deployment.Builds.Add(new Build { Engine = BuildEngines.Dockerfile, CacheHit = true });
            deployment.CompleteStep(DeploymentStep.Build, Now.AddSeconds(20), """{"cacheHit":true}""");
            deployment.ImageRef = "aethera/api:abc";
            deployment.ContainerIds = ["c0ffee"];
            deployment.MarkRunning(Now.AddSeconds(30));
            app.CurrentDeploymentId = deployment.Id;
            db.Add(deployment);
            db.Add(new ImageRecord
            {
                WorkloadId = app.Id, DeploymentId = deployment.Id, ServerId = seed.ServerId,
                Repository = "aethera/api", Tag = "abc", SizeBytes = 1234,
            });
            await db.SaveChangesAsync();
            deploymentId = deployment.Id;
        }

        using (var lease = database.NewContext())
        {
            var db = lease.Db;
            var app = await db.Set<Application>()
                .Include(a => a.GitSource)
                .Include(a => a.BuildConfig)
                .Include(a => a.Ports)
                .Include(a => a.EnvironmentVariables)
                .Include(a => a.Volumes)
                .Include(a => a.Domains)
                .SingleAsync(a => a.Id == appId);

            Assert.Equal(RestartPolicy.OnFailure, app.Runtime.RestartPolicy);
            Assert.Equal(DeploymentStrategies.LowDowntime, app.Runtime.DeploymentStrategy);
            Assert.Equal(1.5, app.Runtime.CpuLimit);
            Assert.Equal(512L * 1024 * 1024, app.Runtime.MemoryLimitBytes);
            Assert.Equal(HealthCheckType.Http, app.Runtime.HealthCheck.Type);
            Assert.Equal("/health", app.Runtime.HealthCheck.Path);
            Assert.Equal(5, app.Runtime.HealthCheck.Retries);
            Assert.Equal(1, app.DeploymentSequence);
            Assert.Equal(deploymentId, app.CurrentDeploymentId);
            Assert.NotNull(app.GitSource);
            Assert.True(app.GitSource!.AutoDeploy);
            Assert.NotNull(app.GitSource.GitCredentialId);
            Assert.Equal("production", app.BuildConfig!.BuildArgs["NODE_ENV"]);
            Assert.Single(app.Ports);
            Assert.Equal(2, app.EnvironmentVariables.Count);
            Assert.Equal("api.turn-one.example", Assert.Single(app.Domains).Hostname);
            Assert.Equal("api-data", Assert.Single(app.Volumes).Name);

            var deployment = await db.Deployments.Include(d => d.Builds).Include(d => d.Steps).SingleAsync(d => d.Id == deploymentId);
            Assert.Equal(DeploymentStatus.Running, deployment.Status);
            Assert.Equal(DeploymentStrategies.LowDowntime, deployment.Strategy);
            Assert.Equal(
                [DeploymentStep.Source, DeploymentStep.Build, DeploymentStep.Running],
                deployment.Steps.Select(x => x.Step).OrderBy(x => x));
            Assert.Equal(StepStatus.Succeeded, deployment.Steps.Single(x => x.Step == DeploymentStep.Build).Status);
            Assert.True(deployment.IsRollbackPoint);
            Assert.Equal(1, deployment.Number);
            Assert.Equal(["c0ffee"], deployment.ContainerIds);
            Assert.Equal(seed.UserId, deployment.TriggeredByUserId);
            Assert.True(Assert.Single(deployment.Builds).CacheHit);
            using var snapshot = JsonDocument.Parse(deployment.ConfigSnapshotJson);
            Assert.Equal("OnFailure", snapshot.RootElement.GetProperty("runtime").GetProperty("restartPolicy").GetString());

            // Enums are stored as readable strings, ids are UUIDv7.
            var raw = await db.Database
                .SqlQueryRaw<string>($"SELECT status AS \"Value\" FROM deployments WHERE id = '{deploymentId}'")
                .SingleAsync();
            Assert.Equal("running", raw);
            Assert.Equal(7, deploymentId.Version);
        }
    }

    private static WorkloadDomain NewDomain(Seed seed, string hostname, string path = "/")
    {
        var domain = new WorkloadDomain { ServerId = seed.ServerId, PathPrefix = path };
        domain.SetHostname(hostname);
        return domain;
    }

    [RequiresDatabaseFact]
    public async Task ServiceAndApplication_ShareOneTable_WithDiscriminator()
    {
        var seed = await SeedBaseAsync();
        Guid serviceId, appId;
        using (var lease = database.NewContext())
        {
            var service = new Service
            {
                EnvironmentId = seed.EnvId, ServerId = seed.ServerId, Name = "Postgres", Slug = Unique("pg"),
                TemplateKey = "postgres", TemplateVersion = "17", Image = "postgres:17", ConfigJson = """{"database":"app"}""",
            };
            var app = NewApp(seed);
            lease.Db.AddRange(service, app);
            await lease.Db.SaveChangesAsync();
            serviceId = service.Id;
            appId = app.Id;
        }

        using (var lease = database.NewContext())
        {
            var all = await lease.Db.Workloads.Where(w => w.Id == serviceId || w.Id == appId).OrderBy(w => w.Slug).ToListAsync();
            Assert.Equal(2, all.Count);
            var service = Assert.IsType<Service>(all.Single(w => w.Id == serviceId));
            Assert.Equal("postgres:17", service.Image);
            using var cfg = JsonDocument.Parse(service.ConfigJson);
            Assert.Equal("app", cfg.RootElement.GetProperty("database").GetString());
            Assert.IsType<Application>(all.Single(w => w.Id == appId));

            var kinds = await lease.Db.Database
                .SqlQueryRaw<string>($"SELECT kind AS \"Value\" FROM workloads WHERE id IN ('{serviceId}','{appId}') ORDER BY kind")
                .ToListAsync();
            Assert.Equal(["application", "service"], kinds);
        }
    }

    [RequiresDatabaseFact]
    public async Task Server_RolesFactsAndStatusesRoundTrip()
    {
        var seed = await SeedBaseAsync();
        Guid id;
        using (var lease = database.NewContext())
        {
            var server = new Server
            {
                OrganizationId = seed.OrgId, Name = Unique("srv"), Host = "10.0.0.5", Roles = [ServerRole.Master, ServerRole.Build],
                Transport = ServerTransport.Agent, PublicIp = "198.51.100.7", AgentVersion = "0.1.0",
            };
            server.Facts.Os = "Ubuntu 24.04";
            server.Facts.CpuCores = 8;
            server.Facts.MemoryBytes = 16L * 1024 * 1024 * 1024;
            server.RecordHeartbeat(Now, DockerStatus.Running);
            lease.Db.Add(server);
            await lease.Db.SaveChangesAsync();
            id = server.Id;
        }

        using (var lease = database.NewContext())
        {
            var server = await lease.Db.Servers.SingleAsync(s => s.Id == id);
            Assert.Equal([ServerRole.Master, ServerRole.Build], server.Roles);
            Assert.Equal("Ubuntu 24.04", server.Facts.Os);
            Assert.Equal(8, server.Facts.CpuCores);
            Assert.Equal(16L * 1024 * 1024 * 1024, server.Facts.MemoryBytes);
            Assert.Equal(AgentStatus.Connected, server.AgentStatus);
            Assert.Equal(DockerStatus.Running, server.DockerStatus);
            Assert.Equal(Now, server.LastHeartbeatAt);

            var withBuildRole = await lease.Db.Servers.Where(s => s.Roles.Contains(ServerRole.Build)).Select(s => s.Id).ToListAsync();
            Assert.Contains(id, withBuildRole);
        }
    }

    [RequiresDatabaseFact]
