    [RequiresDatabaseFact]
    public async Task DomainHostname_IsUniqueAmongActiveRows_AndFreedBySoftDelete()
    {
        var seed = await SeedBaseAsync();
        var firstApp = await SeedAppAsync(seed);
        var secondApp = await SeedAppAsync(seed);
        var host = Unique("site") + ".example.com";

        Guid firstDomainId;
        using (var lease = database.NewContext())
        {
            var domain = NewDomain(seed, host);
            domain.WorkloadId = firstApp;
            lease.Db.Add(domain);
            await lease.Db.SaveChangesAsync();
            firstDomainId = domain.Id;
        }

        using (var lease = database.NewContext())
        {
            var duplicate = NewDomain(seed, host.ToUpperInvariant());
            duplicate.WorkloadId = secondApp;
            lease.Db.Add(duplicate);
            await AssertConstraintAsync(() => lease.Db.SaveChangesAsync(), UniqueViolation);
        }

        using (var lease = database.NewContext())
        {
            // Same host, different path prefix is a different route.
            var other = NewDomain(seed, host, "/docs");
            other.WorkloadId = secondApp;
            lease.Db.Add(other);
            await lease.Db.SaveChangesAsync();
        }

        using (var lease = database.NewContext())
        {
            var first = await lease.Db.Domains.SingleAsync(d => d.Id == firstDomainId);
            first.MarkDeleted(Now);
            await lease.Db.SaveChangesAsync();
        }

        using (var lease = database.NewContext())
        {
            var reused = NewDomain(seed, host);
            reused.WorkloadId = secondApp;
            lease.Db.Add(reused);
            await lease.Db.SaveChangesAsync(); // allowed again
        }
    }

