    [RequiresDatabaseFact]
    public async Task SoftDeletedProjects_AreHiddenByDefault_AndSlugCanBeReused()
    {
        var seed = await SeedBaseAsync();
        var slug = Unique("proj");
        Guid id;
        using (var lease = database.NewContext())
        {
            var project = new Project { OrganizationId = seed.OrgId, Name = "Temp", Slug = slug };
            lease.Db.Add(project);
            await lease.Db.SaveChangesAsync();
            id = project.Id;
        }

        using (var lease = database.NewContext())
        {
            var project = await lease.Db.Projects.SingleAsync(p => p.Id == id);
            project.MarkDeleted(Now);
            await lease.Db.SaveChangesAsync();
        }

        using (var lease = database.NewContext())
        {
            Assert.False(await lease.Db.Projects.AnyAsync(p => p.Id == id));
            Assert.True(await lease.Db.Projects.IgnoreQueryFilters().AnyAsync(p => p.Id == id && p.DeletedAt != null));

            lease.Db.Add(new Project { OrganizationId = seed.OrgId, Name = "Temp again", Slug = slug });
            await lease.Db.SaveChangesAsync();
        }
    }

    [RequiresDatabaseFact]
    public async Task ConcurrentUpdates_AreDetectedWithXmin()
    {
        var seed = await SeedBaseAsync();

        using var first = database.NewContext();
        using var second = database.NewContext();
        var a = await first.Db.Projects.SingleAsync(p => p.Id == seed.ProjectId);
        var b = await second.Db.Projects.SingleAsync(p => p.Id == seed.ProjectId);
        Assert.NotEqual(0u, a.RowVersion);

        a.Description = "from A";
        await first.Db.SaveChangesAsync();

        b.Description = "from B";
        await Assert.ThrowsAsync<DbUpdateConcurrencyException>(() => second.Db.SaveChangesAsync());
    }

    [RequiresDatabaseFact]
    public async Task UpdatedAt_IsStampedOnUpdate()
    {
        var seed = await SeedBaseAsync();
        using var lease = database.NewContext();
        var project = await lease.Db.Projects.SingleAsync(p => p.Id == seed.ProjectId);
        var before = project.UpdatedAt;

        await Task.Delay(20);
        project.Description = "changed";
        await lease.Db.SaveChangesAsync();

        Assert.True(project.UpdatedAt > before);
    }

    [RequiresDatabaseFact]
    public async Task Secret_AllowsAtMostOneScope_AndNamesAreUniquePerScope()
    {
        var seed = await SeedBaseAsync();
        var appId = await SeedAppAsync(seed);

        Secret Make(string name) => NewSecret(seed.OrgId, name);

        using (var lease = database.NewContext())
        {
            var twoScopes = Make("both");
            twoScopes.ProjectId = seed.ProjectId;
            twoScopes.EnvironmentId = seed.EnvId;
            lease.Db.Add(twoScopes);
            await AssertConstraintAsync(() => lease.Db.SaveChangesAsync(), CheckViolation);
        }

        var name = Unique("TOKEN");
        using (var lease = database.NewContext())
        {
            lease.Db.Add(Make(name)); // org scope
            var scoped = Make(name);  // same name, workload scope: allowed
            scoped.WorkloadId = appId;
            lease.Db.Add(scoped);
            await lease.Db.SaveChangesAsync();
        }

        using (var lease = database.NewContext())
        {
            lease.Db.Add(Make(name)); // duplicate at org scope (NULLs compare equal)
            await AssertConstraintAsync(() => lease.Db.SaveChangesAsync(), UniqueViolation);
        }
    }

