    [RequiresDatabaseFact]
    public async Task JobClaim_FollowsAdr0004_SkipLockedPriorityAndLockKeys()
    {
        var type = Unique("test-job");
        var busyKey = Unique("app");
        var org = (await SeedBaseAsync()).OrgId;
        using (var lease = database.NewContext())
        {
            var running = new Job { OrganizationId = org, Type = type, LockKey = busyKey };
            running.Claim("other-worker", Now, TimeSpan.FromMinutes(1));
            lease.Db.AddRange(
                running,
                new Job { OrganizationId = org, Type = type, Priority = 0, RunAfter = Now.AddHours(-3) },
                new Job { OrganizationId = org, Type = type, Priority = 10, RunAfter = Now.AddHours(-2) },
                new Job { OrganizationId = org, Type = type, Priority = 5, RunAfter = Now.AddHours(-1) },
                new Job { OrganizationId = org, Type = type, Priority = 50, RunAfter = Now.AddHours(-1), LockKey = busyKey }, // blocked by the running job
                new Job { OrganizationId = org, Type = type, Priority = 100, RunAfter = Now.AddDays(1) }); // not due yet
            await lease.Db.SaveChangesAsync();
        }

        // The claim statement from ADR 0004 (type filter added to isolate this test).
        const string claim =
            "SELECT j.*, j.xmin FROM jobs j WHERE j.status = 'queued' AND j.type = {0} AND j.run_after <= {1} " +
            "AND (j.lock_key IS NULL OR NOT EXISTS (SELECT 1 FROM jobs r WHERE r.status = 'running' AND r.lock_key = j.lock_key)) " +
            "ORDER BY j.priority DESC, j.run_after, j.id FOR UPDATE SKIP LOCKED LIMIT 1";

        using var one = database.NewContext();
        using var two = database.NewContext();
        await using var txOne = await one.Db.Database.BeginTransactionAsync();
        await using var txTwo = await two.Db.Database.BeginTransactionAsync();

        var first = await one.Db.Jobs.FromSqlRaw(claim, type, Now).SingleAsync();
        var second = await two.Db.Jobs.FromSqlRaw(claim, type, Now).SingleAsync();

        Assert.Equal(10, first.Priority);
        Assert.Equal(5, second.Priority); // the row locked by the first worker was skipped, the blocked key was filtered

        first.Claim("worker-1", Now, TimeSpan.FromMinutes(1));
        second.Claim("worker-2", Now, TimeSpan.FromMinutes(1));
        await one.Db.SaveChangesAsync();
        await two.Db.SaveChangesAsync();
        await txOne.CommitAsync();
        await txTwo.CommitAsync();

        using var check = database.NewContext();
        var stored = await check.Db.Jobs.SingleAsync(j => j.Id == first.Id);
        Assert.Equal(JobStatus.Running, stored.Status);
        Assert.Equal("worker-1", stored.LockedBy);
        Assert.Equal(1, stored.Attempt);
    }

