        using (var lease = database.NewContext())
        {
            lease.Db.Add(new Job { OrganizationId = org, Type = "application.deploy", IdempotencyKey = key });
            lease.Db.Add(new Job { OrganizationId = org, Type = "x" }); // null keys never collide
            lease.Db.Add(new Job { OrganizationId = org, Type = "y" });
            await lease.Db.SaveChangesAsync();
        }

        using var second = database.NewContext();
        second.Db.Add(new Job { OrganizationId = org, Type = "application.deploy", IdempotencyKey = key });
        await AssertConstraintAsync(() => second.Db.SaveChangesAsync(), UniqueViolation);
    }

    [RequiresDatabaseFact]
    public async Task LogChunks_AreKeyedByStreamAndSequence_AndReplayIsIdempotentInSql()
    {
        var streamId = "deploy:" + Guid.CreateVersion7();
        using (var lease = database.NewContext())
        {
            lease.Db.Add(new LogChunk { StreamId = streamId, Sequence = 2, Source = LogSource.Deploy, Stream = LogStream.Stderr, Data = "warn" });
            lease.Db.Add(new LogChunk { StreamId = streamId, Sequence = 1, Source = LogSource.Deploy, Stream = LogStream.Stdout, Data = "hello" });
            await lease.Db.SaveChangesAsync();
        }

        using (var lease = database.NewContext())
        {
            var chunks = await lease.Db.LogChunks.Where(c => c.StreamId == streamId).OrderBy(c => c.Sequence).ToListAsync();
            Assert.Equal(["hello", "warn"], chunks.Select(c => c.Data));
            Assert.Equal(LogStream.Stderr, chunks[1].Stream);

            var smallint = await lease.Db.Database
                .SqlQueryRaw<short>($"SELECT stream AS \"Value\" FROM log_chunks WHERE stream_id = '{streamId}' AND sequence = 2")
                .SingleAsync();
            Assert.Equal((short)2, smallint);

            // ADR 0004 ingest: replay after reconnect must not fail or duplicate.
            var inserted = await lease.Db.Database.ExecuteSqlRawAsync(
                $"INSERT INTO log_chunks (stream_id, sequence, ts, source, stream, data) VALUES ('{streamId}', 1, now(), 2, 1, 'dup') ON CONFLICT (stream_id, sequence) DO NOTHING");
            Assert.Equal(0, inserted);
        }

        using (var lease = database.NewContext())
        {
            lease.Db.Add(new LogChunk { StreamId = streamId, Sequence = 1, Data = "dup" });
            await AssertConstraintAsync(() => lease.Db.SaveChangesAsync(), UniqueViolation);
        }
    }

    [RequiresDatabaseFact]
    public async Task JoinTokens_AreSingleUseByHash_AndTtlIsBounded()
    {
        var seed = await SeedBaseAsync();
        var hash = System.Security.Cryptography.SHA256.HashData(Guid.NewGuid().ToByteArray());
        using (var lease = database.NewContext())
        {
            lease.Db.Add(JoinToken.Issue(seed.ServerId, hash, DateTimeOffset.UtcNow, createdByUserId: seed.UserId));
            await lease.Db.SaveChangesAsync();
        }

        using (var lease = database.NewContext())
        {
            lease.Db.Add(JoinToken.Issue(seed.ServerId, hash, DateTimeOffset.UtcNow));
            await AssertConstraintAsync(() => lease.Db.SaveChangesAsync(), UniqueViolation);
        }

        // The atomic consume statement from ADR 0002.
        using (var lease = database.NewContext())
        {
            const string consume =
                "UPDATE join_tokens SET used_at = now() WHERE token_hash = {0} AND used_at IS NULL AND expires_at > now() RETURNING server_id AS \"Value\"";
            var first = await lease.Db.Database.SqlQueryRaw<Guid>(consume, hash).ToListAsync();
            var replay = await lease.Db.Database.SqlQueryRaw<Guid>(consume, hash).ToListAsync();
            Assert.Equal(seed.ServerId, Assert.Single(first));
            Assert.Empty(replay);
        }

        using (var lease = database.NewContext())
        {
            var tooLong = JoinToken.Issue(seed.ServerId, System.Security.Cryptography.SHA256.HashData([1]), DateTimeOffset.UtcNow, TimeSpan.FromHours(24));
            tooLong.ExpiresAt = tooLong.CreatedAt.AddHours(48);
            lease.Db.Add(tooLong);
            await AssertConstraintAsync(() => lease.Db.SaveChangesAsync(), CheckViolation);
        }
    }

    [RequiresDatabaseFact]
    public async Task AgentCertificates_RevocationIsASerialLookup_AndOnlyOneCaIsActive()
    {
        var seed = await SeedBaseAsync();
        var serial = Unique("serial");
        Guid caId;
        using (var lease = database.NewContext())
        {
            var ca = new CertificateAuthority
            {
                Name = "agent-ca", Subject = "CN=Aethera Agent CA", CertificatePem = "-----BEGIN CERTIFICATE-----", FingerprintSha256 = Unique("fp"),
                NotBefore = Now, NotAfter = Now.AddYears(10), PrivateKeyCiphertext = [1], PrivateKeyNonce = [2], WrappedDataKey = [3], WrappedDataKeyNonce = [4],
                IsActive = false,
            };
            lease.Db.Add(ca);
            lease.Db.Add(new AgentCertificate
            {
                ServerId = seed.ServerId, CertificateAuthority = ca, Serial = serial, FingerprintSha256 = Unique("fp"),
                SubjectUri = $"spiffe://aethera/server/{seed.ServerId}", NotBefore = Now, NotAfter = Now.AddDays(30),
            });
            await lease.Db.SaveChangesAsync();
            caId = ca.Id;
        }

        using (var lease = database.NewContext())
        {
            var cert = await lease.Db.AgentCertificates.SingleAsync(c => c.Serial == serial);
            cert.Revoke("reset agent", Now.AddDays(1));
            await lease.Db.SaveChangesAsync();
        }

        using (var lease = database.NewContext())
        {
            Assert.True(await lease.Db.AgentCertificates.AnyAsync(c => c.Serial == serial && c.RevokedAt != null));

            lease.Db.Add(new AgentCertificate
            {
                ServerId = seed.ServerId, CertificateAuthorityId = caId, Serial = serial, FingerprintSha256 = "x", SubjectUri = "spiffe://x",
            });
            await AssertConstraintAsync(() => lease.Db.SaveChangesAsync(), UniqueViolation);
        }

        CertificateAuthority NewCa(string fp) => new()
        {
            Name = "ca", Subject = "CN=x", CertificatePem = "pem", FingerprintSha256 = fp, PrivateKeyCiphertext = [1], PrivateKeyNonce = [2],
            WrappedDataKey = [3], WrappedDataKeyNonce = [4], IsActive = true,
        };

        using (var lease = database.NewContext())
        {
            lease.Db.Add(NewCa(Unique("fp")));
            await lease.Db.SaveChangesAsync();
        }

        using (var lease = database.NewContext())
        {
            lease.Db.Add(NewCa(Unique("fp")));
            await AssertConstraintAsync(() => lease.Db.SaveChangesAsync(), UniqueViolation); // second active CA
        }
    }

    [RequiresDatabaseFact]
    public async Task DeploymentSteps_PersistAsCheckpointsAndFailureNamesTheStep()
    {
        var seed = await SeedBaseAsync();
        var appId = await SeedAppAsync(seed);
        Guid id;
        using (var lease = database.NewContext())
        {
            var d = Deployment.Queue(appId, seed.EnvId, seed.ServerId, 1, DeploymentTrigger.Manual, Now);
            d.Start("{}", Now);
            d.BeginStep(DeploymentStep.Source, Now);
            d.CompleteStep(DeploymentStep.Source, Now.AddSeconds(1));
            d.SkipStep(DeploymentStep.Build, Now.AddSeconds(1));
            d.BeginStep(DeploymentStep.HealthCheck, Now.AddSeconds(5)).DetailsJson = """{"attempts":3}""";
            d.MarkFailed(DeploymentStep.HealthCheck, "health.timeout", "no 200 within 60s", Now.AddSeconds(65));
            lease.Db.Add(d);
            await lease.Db.SaveChangesAsync();
            id = d.Id;
        }

        using (var lease = database.NewContext())
        {
            var d = await lease.Db.Deployments.Include(x => x.Steps).SingleAsync(x => x.Id == id);
            Assert.Equal(DeploymentStatus.Failed, d.Status);
            Assert.Equal(DeploymentStep.HealthCheck, d.FailedStep);
            Assert.Equal("health.timeout", d.FailureCode);
            Assert.Equal(
                [(DeploymentStep.Source, StepStatus.Succeeded), (DeploymentStep.Build, StepStatus.Skipped), (DeploymentStep.HealthCheck, StepStatus.Failed)],
                d.Steps.OrderBy(x => x.Step).Select(x => (x.Step, x.Status)));
            Assert.Equal("health.timeout", d.Steps.Single(x => x.Step == DeploymentStep.HealthCheck).ErrorCode);

            var stored = await lease.Db.Database
                .SqlQueryRaw<string>($"SELECT step AS \"Value\" FROM deployment_steps WHERE deployment_id = '{id}' ORDER BY started_at, step")
                .ToListAsync();
            Assert.Contains("healthCheck", stored);
        }
    }

    [RequiresDatabaseFact]
    public async Task SecretVersions_AreKeptPerSecret_AndDeletingASecretRemovesThem()
    {
        var seed = await SeedBaseAsync();
        Guid id;
        using (var lease = database.NewContext())
        {
            var secret = NewSecret(seed.OrgId, Unique("DB_PASSWORD"));
            secret.AddVersion([4], new byte[12], [5], new byte[12], masterKeyVersion: 2, Now.AddDays(1));
            lease.Db.Add(secret);
            await lease.Db.SaveChangesAsync();
            id = secret.Id;
        }

        using (var lease = database.NewContext())
        {
            var secret = await lease.Db.Secrets.Include(s => s.Versions).SingleAsync(s => s.Id == id);
            Assert.Equal(2, secret.CurrentVersion);
            Assert.Equal([1, 2], secret.Versions.Select(v => v.Version).Order());
            Assert.Equal(2, secret.Versions.Single(v => v.Version == 2).MasterKeyVersion);

            await lease.Db.Database.ExecuteSqlRawAsync($"DELETE FROM secrets WHERE id = '{id}'");
            Assert.False(await lease.Db.SecretVersions.AnyAsync(v => v.SecretId == id));
        }
    }

