    [RequiresDatabaseFact]
    public async Task IdempotencyRecordsAndSettings_RoundTrip()
    {
        var principal = Guid.CreateVersion7();
        var key = Unique("key");
        using (var lease = database.NewContext())
        {
            lease.Db.Add(new IdempotencyRecord
            {
                PrincipalId = principal, Key = key, Method = "POST", Path = "/api/v1/applications/x/deploy",
                RequestHash = System.Security.Cryptography.SHA256.HashData([1]), ExpiresAt = Now.AddHours(24),
            });
            lease.Db.Add(new InstanceSetting { Key = Unique("update.channel"), ValueJson = "\"stable\"" });
            await lease.Db.SaveChangesAsync();
        }

        using (var lease = database.NewContext())
        {
            var record = await lease.Db.IdempotencyRecords.SingleAsync(r => r.PrincipalId == principal && r.Key == key);
            Assert.Equal(IdempotencyState.InProgress, record.State);
            record.State = IdempotencyState.Completed;
            record.ResponseStatus = 202;
            record.ResponseBody = "{\"id\":1}"u8.ToArray();
            await lease.Db.SaveChangesAsync();
        }

        using (var lease = database.NewContext())
        {
            lease.Db.Add(new IdempotencyRecord
            {
                PrincipalId = principal, Key = key, Method = "POST", Path = "/other", RequestHash = new byte[32], ExpiresAt = Now,
            });
            await AssertConstraintAsync(() => lease.Db.SaveChangesAsync(), UniqueViolation);
        }
    }

